const webhook = $('Webhook - Generate Team Report').first().json;

let body = webhook.body ?? webhook;

// Handle a body that arrives as a JSON string.
if (typeof body === 'string') {
  body = JSON.parse(body);
}

const decisionId = body.decisionId;

if (!decisionId) {
  throw new Error(
    'Missing decisionId. Check the Webhook payload.'
  );
}

// Read opinions submitted by the website.
const perspectives = Array.isArray(body.team_perspectives)
  ? body.team_perspectives
  : [];

if (perspectives.length === 0) {
  throw new Error(
    'No team_perspectives received from the website. ' +
    'Inspect Webhook - Generate Team Report output.'
  );
}

// Prepare the submitted opinions for Gemini.
// Do not filter against old Google Sheets DecisionIDs.
const opinions = perspectives.map(member => ({
  memberName: member.name ?? '',
  email: member.email ?? '',
  role: member.role ?? '',
  preferredAlternative: member.preferred_alternative ?? '',
  reasoning: member.view ?? '',
  concerns: member.concerns ?? '',
  confidence: member.confidence ?? ''
}));

const emails = [
  ...new Set(
    opinions
      .map(opinion => String(opinion.email).trim())
      .filter(email =>
        email &&
        email !== 'member1@example.com' &&
        /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)
      )
  )
];

return [{
  json: {
    decisionId,
    submittedAt: body.submittedAt ?? new Date().toISOString(),
    problem: body.problem ?? '',
    context: body.context ?? '',
    alternatives: body.alternatives ?? [],
    criteria_weights: body.criteria_weights ?? {},
    opinionCount: opinions.length,
    opinions,
    emails
  }
}];

