const response = $input.first().json;

const report =
  response.candidates?.[0]?.content?.parts
    ?.map(part => part.text ?? '')
    .join('\n')
    .trim();

if (!report) {
  throw new Error('Gemini did not return a report.');
}

const previous = $('Code - Prepare Team Data').first().json;

return [{
  json: {
    decisionId: previous.decisionId,
    problem: previous.problem,
    emails: previous.emails,
    report
  }
}];
